export type MasterTag = (typeof TAG_GENRES)[number]['tags'][number]

const _masterTagSet = new Set<string>()
for (const g of TAG_GENRES) {
  for (const t of g.tags) {
    _masterTagSet.add(t)
  }
}

/** マスタタグのラベルかどうか（完全一致） */
export function isMasterTagLabel(label: string): boolean {
  return _masterTagSet.has(label)
}
